package org.mockito.internal.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Timer_isCounting_TriageGen2Test {

    @Test
    public void testIsCounting_ReturnsTrue_WhenWithinDuration() throws InterruptedException {
        // Arrange
        long duration = 500L;
        Timer timer = new Timer(duration);
        timer.start();

        // Act
        boolean result = timer.isCounting();

        // Assert
        assertTrue("isCounting should return true when called immediately after start", result);
    }






}

package org.mockito.internal.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Timer_isCounting_TriageGen2Test {



    @Test
    public void testIsCounting_ReturnsFalse_WhenDurationExceeded() throws InterruptedException {
        // Arrange
        long duration = 10L;
        Timer timer = new Timer(duration);
        timer.start();

        // Act
        // Sleep longer than the duration to ensure elapsed time > durationMillis
        Thread.sleep(duration + 50L);
        boolean result = timer.isCounting();

        // Assert
        assertFalse("isCounting should return false when duration has elapsed", result);
    }




}

