package org.mockito.internal.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Timer_isCounting_TriageGen2Test {







    @Test
    public void testIsCounting_ReturnsTrue_AtExactBoundary() throws InterruptedException {
        // This test attempts to hit the edge case of the <= condition
        // Note: Due to system clock granularity, hitting exact equality is difficult,
        // but we test the logic flow.
        long duration = 1000L;
        Timer timer = new Timer(duration);
        timer.start();

        // Immediately after start, elapsed time is effectively 0 or very small
        assertTrue(timer.isCounting());
    }
}
